def change(amount, coins):
    def f(i, a):               # combinations of the first i coin types making a
        if a == 0:
            return 1
        if i == 0:
            return 0
        c = coins[i - 1]
        ways = f(i - 1, a)
        if c <= a:
            ways += f(i, a - c)
        return ways
    return f(len(coins), amount)

