def change(amount, coins):
    k = len(coins)
    dp = [[0] * (amount + 1) for _ in range(k + 1)]
    for i in range(k + 1):
        dp[i][0] = 1
    for i in range(1, k + 1):
        c = coins[i - 1]
        for a in range(1, amount + 1):
            dp[i][a] = dp[i - 1][a] + (dp[i][a - c] if c <= a else 0)
    return dp[k][amount]

def change(amount, coins):
    prev = [1] + [0] * amount
    for c in coins:
        cur = prev[:]
        for a in range(c, amount + 1):
            cur[a] = prev[a] + cur[a - c]
        prev = cur
    return prev[amount]

def change(amount, coins):
    ways = [1] + [0] * amount
    for c in coins:
        for a in range(c, amount + 1):
            ways[a] += ways[a - c]
    return ways[amount]
